"""Read public Naver responses generated by system Chrome UI navigation.

Uses the nodriver browser backend verified with insane-search on this host.
JSON lines on stdin/stdout; no credentials, request headers or profiles exported.
"""
from __future__ import annotations

import asyncio
import argparse
import base64
import json
import os
import re
import sys
import time
import math
from urllib.parse import urlsplit, parse_qs

import nodriver as uc

API = re.compile(r"^/api/(?:complexes|articles/complex)/([1-9]\d*)$")
MARKERS='/api/complexes/single-markers/2.0'


class Collector:
    def __init__(self, browser, tab, base_url='https://new.land.naver.com'):
        self.browser, self.tab = browser, tab
        self.base_url = base_url
        self.host = urlsplit(base_url).netloc
        self.responses, self.requests = [], {}
        self.error = None
        self.marker_requests,self.marker_pending,self.marker_responses={},{},[]
        self.map_active=False

    async def started(self,event):
        parsed=urlsplit(event.request.url)
        if parsed.netloc==self.host and parsed.path==MARKERS:self.marker_pending[event.request_id]=str(event.loader_id)

    async def failed(self,event):
        if self.marker_pending.pop(event.request_id,None) is not None:
            self.marker_requests.pop(event.request_id,None)
            if self.map_active and not event.canceled:self.error='unavailable'

    async def response(self, event):
        parsed = urlsplit(event.response.url)
        if parsed.netloc==self.host and event.response.mime_type=='text/html' and os.environ.get('NAVER_BROWSER_DIAGNOSTICS')=='1':
            print(json.dumps({'stage':'document-response','path':parsed.path,'status':int(event.response.status)}),file=sys.stderr,flush=True)
        if parsed.netloc == self.host and API.fullmatch(parsed.path):
            self.requests[event.request_id] = (event.response.url, int(event.response.status))
        elif parsed.netloc==self.host and parsed.path==MARKERS:
            self.marker_requests[event.request_id]=(event.response.url,int(event.response.status),str(event.loader_id))

    async def finished(self, event):
        marker=self.marker_requests.pop(event.request_id,None)
        self.marker_pending.pop(event.request_id,None)
        record = marker or self.requests.pop(event.request_id, None)
        if not record:
            return
        url,status=record[:2]
        if status in (401, 403, 429):
            self.error = "rate_limited" if status == 429 else "unauthorized"
            return
        try:
            body, encoded = await self.tab.send(uc.cdp.network.get_response_body(event.request_id))
            if encoded:
                body = base64.b64decode(body).decode("utf-8")
            payload = json.loads(body)
            if marker:
                if not isinstance(payload,list) or len(payload)>5000:raise ValueError('invalid markers')
                self.marker_responses.append({'loader':marker[2],'payload':payload,'received':time.monotonic()})
                self.marker_responses=self.marker_responses[-20:]
            else:self.responses.append({"url": url, "status": status, "payload": payload})
        except Exception as error:
            print(json.dumps({"path": urlsplit(url).path, "status": status, "error": type(error).__name__, "reason": str(error)[:160]}),file=sys.stderr,flush=True)
            self.error = "invalid_response"

    def complete(self, complex_no, first_page_only=False):
        pages = {}
        for record in self.responses:
            parsed = urlsplit(record["url"])
            if parsed.path == f"/api/articles/complex/{complex_no}":
                params = parse_qs(parsed.query)
                if params.get("sameAddressGroup") == ["false"] and params.get("tradeType") == ["A1"] and params.get("realEstateType") == ["APT"]:
                    pages[int(params.get("page", ["1"])[0])] = record["payload"]
        if not pages:
            return False
        if first_page_only and 1 in pages:
            return True
        last = max(pages)
        return all(i in pages for i in range(1, last + 1)) and pages[last].get("isMoreData") is False

    def captured_detail(self,complex_no,base=None):
        if base is None:
            candidates=[record['payload'][key] for record in self.responses if urlsplit(record['url']).path==f'/api/complexes/{complex_no}' for key in ['complex','complexDetail'] if isinstance(record['payload'].get(key),dict) and str(record['payload'][key].get('complexNo',''))==complex_no]
            if not candidates:return None
            complete=[value for value in candidates if value.get('detailAddress') and (value.get('cortarAddress') or value.get('address'))]
            return self.captured_detail(complex_no,(complete or candidates)[-1])
        observed=dict(base) if base else None
        compact=lambda value:re.sub(r'\s','',re.sub(r'(?:\s*\([^)]*\))+\s*$','',str(value or '')))
        def road(value):
            prefix=value.get('roadAddressPrefix','');suffix=value.get('roadAddress','')
            return str(suffix) if compact(suffix).startswith(compact(prefix)) else str(prefix)+' '+str(suffix)
        for record in self.responses:
            if urlsplit(record['url']).path!=f'/api/complexes/{complex_no}':continue
            for key in ['complex','complexDetail']:
                value=record['payload'].get(key)
                if not isinstance(value,dict) or str(value.get('complexNo',''))!=complex_no:continue
                if base:
                    if value.get('cortarAddress') or value.get('address'):
                        if compact(value.get('cortarAddress') or value.get('address'))!=compact(base.get('cortarAddress') or base.get('address')):continue
                    if value.get('detailAddress') and compact(value['detailAddress'])!=compact(base.get('detailAddress')):continue
                    if value.get('roadAddress') and base.get('roadAddress') and compact(road(value))!=compact(road(base)):continue
                observed={**(observed or {}),**value}
        return observed

    async def detail(self, complex_no):
        observed=self.captured_detail(complex_no)
        # Initial complex information is server-rendered and need not generate
        # an API response. Read the address table actually displayed by the UI.
        await self.tab.evaluate("Array.from(document.querySelectorAll('button')).find(b=>['단지정보','단지정보 더보기'].includes(b.textContent.trim()))?.click()")
        for _ in range(20):
            observed=self.captured_detail(complex_no)
            visible = json.loads(await self.tab.evaluate("JSON.stringify((()=>{const th=Array.from(document.querySelectorAll('th')).find(t=>t.textContent.trim()==='주소');return th?{address:th.nextElementSibling.innerText,road:th.nextElementSibling.querySelector('.icon_roadname')?.closest('p')?.innerText.trim(),title:document.querySelector('#complexTitle')?.innerText}:null})())"))
            if visible and visible.get("address"):
                parcel = next((line.strip() for line in visible["address"].splitlines() if line.strip()), "")
                match = re.fullmatch(r"(.*(?:동|읍|면))\s+(산?\s*\d+(?:-\d+)?)", parcel)
                if match and visible.get("title"):
                    base={"complexNo": complex_no, "complexName": visible["title"], "cortarAddress": match.group(1), "detailAddress": match.group(2),**({'roadAddressPrefix':'','roadAddress':visible['road']} if visible.get('road') else {})}
                    for attempt in range(9):
                        merged=self.captured_detail(complex_no,base)
                        if merged and merged.get('latitude') is not None and merged.get('longitude') is not None:return merged
                        if attempt<8:await asyncio.sleep(0.2)
                    return merged
                # Redevelopment parcels can use a block label. A visible table
                # alone is not a reason to stop waiting for its detail response.
                if observed and observed.get('detailAddress') and (observed.get('cortarAddress') or observed.get('address')) and observed.get('roadAddress'):
                    return observed
            await asyncio.sleep(0.5)
        return self.captured_detail(complex_no) or observed

    async def inspect(self, request):
        self.responses,self.requests,self.error=[],{},None
        complex_no=request.get('complexNo','')
        if not re.fullmatch(r'[1-9]\d{0,11}',complex_no):return {'errorCode':'unmatched'}
        _,loader_id,*_=await self.tab.send(uc.cdp.page.navigate(f'{self.base_url}/complexes/{complex_no}?a=APT&b=A1&e=RETAIL'))
        for _ in range(40):
            if self.error:return {'errorCode':self.error}
            frame=await self.tab.send(uc.cdp.page.get_frame_tree())
            if not loader_id or frame.frame.loader_id==loader_id:
                text=await self.tab.evaluate("document.body?.innerText||''")
                if re.search(r'자동입력\s*방지|비정상적인\s*접근|접근이?\s*제한|Too Many Requests|captcha',text,re.I):return {'errorCode':'blocked'}
                if '/404' in (await self.tab.evaluate('location.href')):return {'errorCode':'site_unavailable'}
                ready=await self.tab.evaluate("document.readyState==='complete'&&!!document.querySelector('#complexTitle')?.innerText")
                if ready:
                    current=await self.tab.evaluate('location.href')
                    if urlsplit(current).path.rstrip('/')!=f'/complexes/{complex_no}':return {'errorCode':'address_mismatch'}
                    detail=await self.detail(complex_no)
                    if self.error:return {'errorCode':self.error}
                    buildings=sorted({article.get('buildingName','') for record in self.responses if urlsplit(record['url']).path==f'/api/articles/complex/{complex_no}' for article in record['payload'].get('articleList',[]) if article.get('realEstateTypeCode') in ('APT','JGC') and article.get('tradeTypeCode')=='A1' and article.get('articleStatus','R0')=='R0' and article.get('buildingName')})
                    return {'complexNo':complex_no,'complexDetail':detail,'article_building_dongs':buildings[:1000]} if detail else {'errorCode':'address_mismatch'}
            await asyncio.sleep(0.25)
        return {'errorCode':'timeout'}

    async def collect(self, request):
        self.responses, self.requests, self.error = [], {}, None
        complex_no = request.get("complexNo")
        if not complex_no or not re.fullmatch(r"[1-9]\d{0,11}", complex_no):
            return {"errorCode": "unmatched"}
        if os.environ.get('NAVER_BROWSER_DIAGNOSTICS')=='1':
            print(json.dumps({'stage':'navigate','complexNo':complex_no}),file=sys.stderr,flush=True)
        await self.tab.send(uc.cdp.page.navigate(f"{self.base_url}/complexes/{complex_no}?a=APT&b=A1&e=RETAIL"))
        started = time.monotonic()
        deadline = started + request.get("timeoutSeconds", 45)
        selected = False
        while time.monotonic() < deadline:
            if self.error:
                return {"errorCode": self.error}
            current = await self.tab.evaluate("location.href")
            match = re.search(r"/complexes/([1-9]\d*)", current or "")
            if match:
                found = match.group(1)
                if complex_no and found != complex_no:
                    return {"errorCode": "address_mismatch"}
                complex_no = found
                if not selected:
                    selected = await self.tab.evaluate("(()=>{const c=document.querySelector('#address_group2');if(!c)return false;if(c.checked)c.click();return true})()")
                if self.complete(complex_no, request.get('firstPageOnly',False)):
                    detail = await self.detail(complex_no)
                    if not detail:
                        return {"errorCode": "address_mismatch"}
                    return {"complexNo": complex_no, "complexDetail": detail, "responses": self.responses}
                if not request.get('firstPageOnly',False):
                    await self.tab.evaluate("(()=>{for(let e=document.querySelector('#articleListArea');e;e=e.parentElement){if(e.scrollHeight>e.clientHeight){e.scrollTop=e.scrollHeight;e.dispatchEvent(new Event('scroll',{bubbles:true}));}}})()")
            text = await self.tab.evaluate("document.body?.innerText || ''")
            if re.search(r"자동입력\s*방지|비정상적인\s*접근|접근이?\s*제한|Too Many Requests|captcha", text, re.I):
                return {"errorCode": "blocked"}
            if "/404" in (current or ""):
                return {"errorCode": "site_unavailable"}
            await asyncio.sleep(1.5)
        print(json.dumps({"captured":[{"path":urlsplit(r['url']).path,"query":urlsplit(r['url']).query,"more":r['payload'].get('isMoreData')} for r in self.responses]}),file=sys.stderr,flush=True)
        return {"errorCode": "incomplete" if complex_no else "unmatched"}

    async def search(self, query):
        _, loader_id, *_ = await self.tab.send(uc.cdp.page.navigate(self.base_url+'/'))
        opened=False
        for _ in range(30):
            try:
                frame=await self.tab.send(uc.cdp.page.get_frame_tree())
                if loader_id and frame.frame.loader_id!=loader_id:
                    await asyncio.sleep(0.3)
                    continue
                opened=await self.tab.evaluate("(()=>{if(document.readyState!=='complete')return false;const b=Array.from(document.querySelectorAll('button')).find(b=>b.textContent.trim()==='단지, 지역검색');if(!b)return false;b.click();return true})()")
            except Exception:
                opened=False
            if opened:break
            await asyncio.sleep(0.3)
        if not opened:raise asyncio.TimeoutError()
        for _ in range(30):
            try:
                focused=await self.tab.evaluate("(()=>{const field=document.querySelector('#land_search');if(!field?.getClientRects().length)return false;Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set.call(field,'');field.dispatchEvent(new Event('input',{bubbles:true}));field.focus();return true})()")
            except Exception:
                focused=False
            if focused:break
            await asyncio.sleep(0.3)
        if not focused:raise asyncio.TimeoutError()
        await self.tab.send(uc.cdp.input_.insert_text(query))
        previous=None
        for _ in range(30):
            choices=json.loads(await self.tab.evaluate("JSON.stringify(Array.from(document.querySelectorAll('li.search_item:not(.type_recent) button.search_button')).map(b=>b.getClientRects().length?b.innerText.trim():''))"))
            value=await self.tab.evaluate("document.querySelector('#land_search')?.value")
            if any(choices) and value==query and choices==previous:return choices
            previous=choices if value==query else None
            text=await self.tab.evaluate("document.body?.innerText||''")
            if re.search(r'captcha|접근.*제한|비정상적인.*접근',text,re.I):
                raise PermissionError('blocked')
            if '/404' in (await self.tab.evaluate('location.href')):
                raise ConnectionError('site_unavailable')
            await asyncio.sleep(0.3)
        return []

    async def discover(self, request):
        if request.get('location') is not None:return await self.discover_location(request)
        query=request.get('query','')
        names=request.get('names',[])
        phase=request.get('phase')
        if phase is not None and (not isinstance(phase,str) or not re.fullmatch(r'\d{1,3}',phase)):return {'errorCode':'unmatched'}
        def phase_allowed(value):
            values=re.findall(r'(\d+(?:-\d+)?)(?:단지|차)',value)
            return not phase or not values or any(value==phase or '-' in value for value in values)
        if not isinstance(query,str) or not 0<len(query)<=300 or not isinstance(names,list) or not names or len(names)>100:
            return {'errorCode':'unmatched'}
        normalize=lambda value:re.sub(r'[\s()[\]·.,_-]|아파트','',value).lower()
        names=[normalize(name) for name in names if isinstance(name,str) and len(name)<=300]
        dong=normalize(request.get('dong',''))
        choices=await self.search(query)
        selected=[(index,label) for index,label in enumerate(choices) if phase_allowed(label) and any(name and (name==normalize(label) or dong and normalize(label).startswith(dong) and name==normalize(label)[len(dong):] or len(name)>=4 and name in normalize(label)) for name in names)]
        if os.environ.get('NAVER_BROWSER_DIAGNOSTICS')=='1':
            print(json.dumps({'stage':'search','choices':len(choices),'matched':len(selected),'phase':phase,'labels':choices},ensure_ascii=False),file=sys.stderr,flush=True)
        if not selected or len(selected)>8:return {'candidates':[]}
        candidates=[]
        for number,(index,label) in enumerate(selected):
            if number:
                current=await self.search(query)
                positions=[position for position,value in enumerate(current) if value==label]
                if len(positions)!=1:
                    if os.environ.get('NAVER_BROWSER_DIAGNOSTICS')=='1':print(json.dumps({'stage':'reselect','expected':label,'current':current},ensure_ascii=False),file=sys.stderr,flush=True)
                    return {'errorCode':'unmatched'}
            clicked=await self.tab.evaluate("(label=>{const buttons=Array.from(document.querySelectorAll('li.search_item:not(.type_recent) button.search_button')).filter(element=>element.getClientRects().length&&element.innerText.trim()===label);if(buttons.length!==1)return false;buttons[0].dispatchEvent(new MouseEvent('mousedown',{bubbles:true,cancelable:true,button:0}));return true})("+json.dumps(label)+")")
            if not clicked:
                if os.environ.get('NAVER_BROWSER_DIAGNOSTICS')=='1':print(json.dumps({'stage':'click','expected':label,'current':await self.tab.evaluate("JSON.stringify(Array.from(document.querySelectorAll('li.search_item button.search_button')).map(e=>({text:e.innerText,visible:!!e.getClientRects().length})))")},ensure_ascii=False),file=sys.stderr,flush=True)
                return {'errorCode':'unmatched'}
            for _ in range(40):
                current=await self.tab.evaluate('location.href')
                match=re.fullmatch(r'/complexes/([1-9]\d{0,11})/?',urlsplit(current).path)
                name=await self.tab.evaluate("document.querySelector('#complexTitle')?.innerText||''")
                if match and name and phase_allowed(name):
                    candidates.append({'complexNo':match.group(1),'name':name.strip()})
                    break
                markers=json.loads(await self.tab.evaluate("JSON.stringify(Array.from(document.querySelectorAll('a[id$=COMPLEX]')).map(e=>({complexNo:e.id.replace(/COMPLEX$/,''),name:e.querySelector('.complex_title')?.textContent.trim()||''})))"))
                matched=[marker for marker in markers if phase_allowed(marker['name']) and re.fullmatch(r'[1-9]\d{0,11}',marker['complexNo']) and any(expected and (expected==normalize(marker['name']) or len(expected)>=4 and expected in normalize(marker['name'])) for expected in names)]
                if matched:
                    candidates.extend(matched)
                    break
                await asyncio.sleep(0.25)
        unique={candidate['complexNo']:candidate for candidate in candidates}
        return {'candidates':list(unique.values())} if len(unique)<=8 else {'errorCode':'unmatched'}

    async def discover_location(self,request):
        self.map_active=True
        try:return await self._discover_location(request)
        finally:self.map_active=False

    async def _discover_location(self,request):
        location=request.get('location')
        if not isinstance(location,dict):return {'errorCode':'unmatched'}
        latitude,longitude=location.get('latitude'),location.get('longitude')
        if isinstance(latitude,bool) or isinstance(longitude,bool) or not isinstance(latitude,(int,float)) or not isinstance(longitude,(int,float)) or not 28<=latitude<=40 or not 122<=longitude<=135:return {'errorCode':'unmatched'}
        self.marker_responses=[];self.marker_requests={};self.marker_pending={};self.error=None
        started=time.monotonic()
        _,loader_id,*_=await self.tab.send(uc.cdp.page.navigate(f'{self.base_url}/complexes?ms={latitude},{longitude},17&a=APT&b=A1&e=RETAIL'))
        def nearby(marker):
            lat,lon=marker.get('latitude'),marker.get('longitude')
            if isinstance(lat,bool) or isinstance(lon,bool) or not isinstance(lat,(int,float)) or not isinstance(lon,(int,float)) or not 28<=lat<=40 or not 122<=lon<=135:return False
            dlat,dlon=math.radians(lat-latitude),math.radians(lon-longitude)
            distance=2*6371008.8*math.asin(min(1,math.sqrt(math.sin(dlat/2)**2+math.cos(math.radians(lat))*math.cos(math.radians(latitude))*math.sin(dlon/2)**2)))
            return distance<=1000
        for _ in range(100):
            if self.error:return {'errorCode':self.error}
            text=await self.tab.evaluate("document.body?.innerText||''")
            if re.search(r'자동입력\s*방지|비정상적인\s*접근|접근이?\s*제한|Too Many Requests|captcha',text,re.I):return {'errorCode':'blocked'}
            if '/404' in (await self.tab.evaluate('location.href')):return {'errorCode':'site_unavailable'}
            batches=[batch for batch in self.marker_responses if batch['loader']==str(loader_id)]
            pending=any(loader==str(loader_id) for loader in self.marker_pending.values())
            if batches and not pending and time.monotonic()-started>=2:
                batch=batches[-1]
                candidates=[]
                for marker in batch['payload']:
                    if not isinstance(marker,dict) or marker.get('markerType')!='COMPLEX':continue
                    if not re.fullmatch(r'[1-9]\d{0,11}',str(marker.get('markerId',''))) or not isinstance(marker.get('complexName'),str) or len(marker['complexName'])>300:return {'errorCode':'invalid_response'}
                    lat,lon=marker.get('latitude'),marker.get('longitude')
                    if isinstance(lat,bool) or isinstance(lon,bool) or not isinstance(lat,(int,float)) or not isinstance(lon,(int,float)) or not 28<=lat<=40 or not 122<=lon<=135:return {'errorCode':'invalid_response'}
                    if nearby(marker):candidates.append({'complexNo':str(marker['markerId']),'name':marker['complexName'],'latitude':marker['latitude'],'longitude':marker['longitude']})
                if candidates and time.monotonic()-batch['received']>=0.5:
                    return {'candidates':list({candidate['complexNo']:candidate for candidate in candidates}.values()),'discovery':'map','sourceUrl':await self.tab.evaluate('location.href')}
            await asyncio.sleep(0.25)
        return {'errorCode':'timeout'}


async def main():
    parser=argparse.ArgumentParser()
    parser.add_argument('--base-url',default='https://new.land.naver.com')
    args=parser.parse_args()
    for attempt in range(3):
        try:
            browser = await uc.start(headless=os.environ.get('NAVER_CHROME_HEADLESS')=='1',browser_executable_path=os.environ.get('NAVER_CHROME_PATH') or None,browser_args=['--lang=ko-KR','--window-size=1280,1000'])
            break
        except Exception:
            for instance in list(uc.util.get_registered_instances()):
                process=getattr(instance,'_process',None)
                if process and process.stderr and os.environ.get('NAVER_BROWSER_DIAGNOSTICS')=='1':
                    try:
                        error=await asyncio.wait_for(process.stderr.read(4096),timeout=1)
                        print(error.decode('utf-8',errors='replace'),file=sys.stderr,flush=True)
                    except (asyncio.TimeoutError,ValueError,RuntimeError):pass
                instance.stop()
            if attempt==2:raise
            await asyncio.sleep(1)
    try:
        # Create the site target from the browser connection; do not wait for a cross-site Page.navigate acknowledgement.
        tab = await asyncio.wait_for(browser.get(args.base_url+'/',new_tab=True),timeout=15)
        collector = Collector(browser, tab,args.base_url)
        tab.add_handler(uc.cdp.network.ResponseReceived, collector.response)
        tab.add_handler(uc.cdp.network.LoadingFinished, collector.finished)
        tab.add_handler(uc.cdp.network.RequestWillBeSent,collector.started)
        tab.add_handler(uc.cdp.network.LoadingFailed,collector.failed)
        await tab.send(uc.cdp.network.enable(max_total_buffer_size=64000000, max_resource_buffer_size=8000000, enable_durable_messages=True))
        print(json.dumps({"ready": True}), flush=True)
        while line := await asyncio.to_thread(sys.stdin.readline):
            request = json.loads(line)
            if request.get("close"):
                break
            try:
                operation=collector.discover(request) if request.get('discover') else collector.inspect(request) if request.get('inspect') else collector.collect(request)
                result = await asyncio.wait_for(operation,timeout=request.get('timeoutSeconds',45))
            except asyncio.TimeoutError:
                if os.environ.get('NAVER_BROWSER_DIAGNOSTICS')=='1':
                    try:
                        state=await asyncio.wait_for(tab.evaluate("JSON.stringify({path:location.pathname,title:document.title,body:document.body?.innerText.slice(0,300)})"),timeout=3)
                        print(json.dumps({'stage':'navigation-timeout','state':json.loads(state),'responses':len(collector.responses)}),file=sys.stderr,flush=True)
                    except Exception:pass
                result = {"errorCode": "timeout"}
            except PermissionError:
                result = {"errorCode": "blocked"}
            except ConnectionError:
                result = {"errorCode": "site_unavailable"}
            except Exception as error:
                print(type(error).__name__+": "+str(error)[:180], file=sys.stderr, flush=True)
                result = {"errorCode": "unavailable"}
            if collector.error in ['rate_limited','unauthorized','blocked']:result={'errorCode':collector.error}
            print(json.dumps(result, ensure_ascii=False), flush=True)
    finally:
        browser.stop()


if __name__ == "__main__":
    asyncio.run(main())
